    bio:'Стоит у двери магазина на Баумана и вполголоса называет номер каждому, кто вошёл. Голубя тоже считает, если тот переступил порог, и не гонит: карманов у птицы нет. После смены пьёт чай стоя и закрывает счёт до завтра.',
