    do:['tip','help_ask'],
    look:{hat:'none', coat:'#BE123C', item:'bag'},
    lines:[
      'Хлопни один раз в арке, если не трудно. Мне своё эхо уже врёт.',
      'Эта — семёрка. Третья арка на Баумана вчера была девять, пока не повесили афишу.',
      'До Кремля ещё один поворот. Там эхо толстое, стена близко.',
      'Середину дорожки не занимаю. Хлопать надо с краю, иначе оценка про людей, не про камень.',
      'Блокнот мокрый — оценка не считается. Честность важнее цифры.',
      'Домой по Петербургской. Там арки тихие, я их не трогаю после шести.'
    ],
    day:[[0,'home'],[9,'work'],[14,'haunt'],[18,'home']],
    dayOff:[[0,'home'],[11,'work'],[16,'home']],
