    do:['gossip','help_ask','tip'],
    look:{hat:'beanie', coat:'#44403C', item:'broom'},
    lines:[
      'Опиши перчатку. Если она на проволоке — сниму. Если нет, значит, ещё гуляет.',
      'Красная левая висит третий день. Правая, видимо, выбрала свободу.',
      'Помоги докатить бак до угла. Дальше он сам, если верить колёсам.',
      'Двор сухой по краю. Середина ещё помнит вчерашний дождь.',
      'До Мавлютова через арку. Через газон я тебя не провожаю.',
      'Проволока моя, перчатки чужие. Разницу я помню лучше жильцов.',
      'Вечером гирлянда остаётся. Я ухожу, она дежурит.'
    ],
    day:[[0,'home'],[6,'work'],[15,'haunt'],[19,'home']],
    dayOff:[[0,'home'],[10,'work'],[15,'home']],
