      'До Фучика донесёшь, если не положишь в горячий пакет к хлебу.',
      'Сдачи мелочь. Бумажка мнётся о зелень, обоим неприятно.',
      'Слышала, электричка опять позже. Значит, к вечеру будет тише.',
      'После шести пучки мои, не твои. Я гуляю с ними до дома.'
