      'До площади по краю. Середина ещё сохнет.',
      'Фантики летят с Восстания. У них расписание лучше автобуса.',
      'Лавка слева мокрая. Справа можно, я проверяла.',
      'Пять минут в тени — моя лишняя зарплата. Потом опять метла.'
